<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\UserInvitation\Domain\ValueObject\Accessor\UserInvitationEmailAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the UserInvitationEmailAccessor trait.
 *
 * Covers null default, string/VO assignment via withEmail,
 * getEmail/email accessors, and isEmailChanged with/without original.
 */
class UserInvitationEmailAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withEmail creates a new instance with the Email set
     * from a string value, and getEmail returns the primitive string.
     */
    public function testWithEmailFromString(): void
    {
        // Arrange
        $holder = new ImplWithUserInvitationEmailAccessorUnitTest();

        // Act
        $result = $holder->withEmail('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->getEmail());
    }
    /**
     * Asserts that withemail has access to the value object
     * from a string value, and getEmail returns the primitive string.
     */
    public function testWithEmailFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithUserInvitationEmailAccessorUnitTest();

        // Act
        $result = $holder->withEmail('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->email()->value());
    }
    public function testChangedEmail(): void
    {
        // Arrange
        $holder = new ImplWithUserInvitationEmailAccessorUnitTest()->withEmail('one');
        $original = $holder->withEmail('one');
        $same = $holder->withEmail('one');
        $modified = $holder->withEmail('other');

        // Act
        $withSame = $original->isEmailChanged($same);
        $withDiferent = $original->isEmailChanged($modified);

        // Assert
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithUserInvitationEmailAccessorUnitTest
{
    use UserInvitationEmailAccessor;
}
